def export_orders(db):
    ids = db.execute('SELECT id FROM orders ORDER BY id').fetchall()
    return [(identifier, db.execute('SELECT total FROM orders WHERE id = ?', (identifier,)).fetchone()[0])
            for (identifier,) in ids]

